//! Actual149 actor retirement/admission; host save acknowledgement is simulated here.
//! Durable storage is independently covered by native SQLite/restart campaigns.
use gielinor_world::{consumable_clocks::{Rules,Policy,Kind},food::Edible,inventory::Item,npc::RandomSource,simulation::{World,PlayerData,WorldEvent,Action},stats::Stats,CoordGrid};
struct Fixed;impl RandomSource for Fixed{fn below(&mut self,_:u32)->u32{panic!("fixed food drew RNG")}}
#[test]
fn new_actor_generation_never_inherits_old_category_or_attack_contribution(){
 let mut count=0;
 for slot in[0,13,27]{for combo in[false,true]{
  let id=if combo{2162}else{7521};let other=(slot+1)%28;let mut w=World::default();w.collision.allocate(3224,3216,0);w.foods.insert(id,Edible{id,heal:2,delay:30,replacement:if combo{None}else{Some(7523)},message:"Food".into()});w.member_foods.insert(id);w.slot_preserving_foods.insert(id);let mut rules=Rules::default();rules.foods.insert(id,Policy{kind:if combo{Kind::ComboFood}else{Kind::Food},consume_delay:30,combat_delay:2,members:true});w.consumable_rules=Some(rules);
  let mut stats=Stats::default();stats.set_base(3,99);stats.set_current(3,50);stats.set_fine_xp(3,130344311).unwrap();let mut data=PlayerData::new(1,"Independent fresh actor".into(),CoordGrid::new(3224,3218,0).unwrap(),stats);for s in 0..28{data.inventory.restore_slot(s,Some(Item{id:if s==slot||s==other{id}else{1931},count:1,vars:0})).unwrap();}w.queue_login(1,data).unwrap();w.tick_with_random(&mut Fixed).unwrap();let old=w.actors().next().unwrap();w.set_membership(old,true).unwrap();w.set_next_attack_delay(old,100).unwrap();let start=w.clock.0;w.submit(old,Action::EatItemSlot{slot,item:id}).unwrap();w.tick_with_random(&mut Fixed).unwrap();assert!(w.is_attack_delayed(old).unwrap());w.drain_events();
  w.request_logout(old).unwrap();let saved=w.drain_events().into_iter().find_map(|e|if let WorldEvent::Save{actor,data}=e{assert_eq!(actor,old);Some(data)}else{None}).expect("actual logout save boundary");assert!(w.queue_login(2,saved.clone()).is_err(),"account must remain reserved before acknowledgement");w.saved(old).unwrap();for _ in 0..4{w.tick_with_random(&mut Fixed).unwrap();if w.actors().next().is_none(){break;}}assert!(w.actors().next().is_none());assert!(w.data(old).is_err());
  w.queue_login(2,saved).unwrap();w.tick_with_random(&mut Fixed).unwrap();let new=w.actors().next().unwrap();assert_ne!(new.generation,old.generation);assert!(w.clock.0<start+30);assert!(!w.is_attack_delayed(new).unwrap());assert!(w.data(old).is_err());w.set_membership(new,true).unwrap();w.drain_events();w.submit(new,Action::EatItemSlot{slot:other,item:id}).unwrap();w.tick_with_random(&mut Fixed).unwrap();let p=w.data(new).unwrap();assert_eq!(p.stats.current(3),54);assert_eq!(p.stats.fine_xp(3),130344311);assert_eq!(p.inventory.get(other).map(|v|v.id),if combo{None}else{Some(7523)});assert_eq!(w.drain_events().iter().filter(|e|matches!(e,WorldEvent::FoodTransition{..})).count(),1);count+=1;
 }}
 assert_eq!(count,6);println!("PG_CONSUMABLE_FRESH6 actualretirement/newgeneration sameaccount;unacknowledgedreservation;newactorFood/Combo andattackclockfresh beforeold30ticksentinel expires PASS;memoryackonly,notdurablestorageclaim");
}
